Envoy Service Mesh.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Envoy Service Mesh container

Container_Boundary(envoy_service_mesh, "Envoy Service Mesh") {
    Component(Envoy_Proxy_Edge_Router, "Envoy Proxy Edge Router", "Envoy, C++", "Handles edge ingress routing, TLS termination, and forwards authenticated traffic to internal services.")
    Component(SPIFFE_SPIRE_Workload_Attestation_Agent, "SPIFFE/SPIRE Workload Attestation Agent", "SPIFFE/SPIRE", "Provides automated workload identity and issues X.509 certificates for mTLS communication.")
    Component(Authorization_Policy_Enforcer, "Authorization Policy Enforcer", "Open Policy Agent (OPA), ext_authz", "Enforces strict RBAC and fine-grained access control policies for inter-service traffic.")
}

Rel(Envoy_Proxy_Edge_Router, Authorization_Policy_Enforcer, "Validates ingress and inter-service requests via ext_authz", "gRPC / mTLS")
Rel(Envoy_Proxy_Edge_Router, SPIFFE_SPIRE_Workload_Attestation_Agent, "Retrieves mTLS certificates for secure workload identification", "API / IPC")

@enduml

Amazon S3.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_s3, "Amazon S3") {
    Component(bookstore_assets_prod, "bookstore-assets-prod", "Amazon S3 Bucket", "Stores static frontend assets delivered via Amazon CloudFront OAC.")
    Component(bookstore_digital_products_prod, "bookstore-digital-products-prod", "Amazon S3 Bucket", "Stores digital e-book downloads accessed via 15-minute Amazon S3 Presigned URLs.")
    Component(bookstore_backups_prod, "bookstore-backups-prod", "Amazon S3 Bucket", "Stores multi-region system backups and archived assets.")
}

Rel(bookstore_assets_prod, bookstore_digital_products_prod, "Replicates data", "Amazon S3 Cross-Region Replication (CRR)")
Rel(bookstore_digital_products_prod, bookstore_backups_prod, "Replicates data", "Amazon S3 Cross-Region Replication (CRR)")

@enduml

Amazon EventBridge.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Amazon EventBridge container

Container_Boundary(amazon_eventbridge, "Amazon EventBridge") {
    Component(Store_Domain_Event_Bus, "Store Domain Event Bus", "AWS EventBridge Custom Bus", "Receives and routes domain events from the Order & Checkout Service and other microservices.")
    Component(Event_Schema_Registry, "Event Schema Registry", "Amazon EventBridge Schema Registry", "Validates and manages event schemas for decoupled event-driven integration.")
}

Rel(Store_Domain_Event_Bus, Event_Schema_Registry, "Validates event payloads against registered schemas via AWS API", "AWS API / HTTPS")

@enduml
